import { jsx as _jsx } from "react/jsx-runtime";
import { render } from "@testing-library/react";
import { Switch } from "@mui/material";
import { describe, it, expect } from "vitest";
import "@testing-library/jest-dom/vitest";
import { RDSThemeProvider } from "../../../rdsThemeProvider";
import { testThemeConfigurations } from "./helpers";
testThemeConfigurations.forEach(({ themeName, themeMap, palettes }) => {
    Object.entries(palettes).forEach(([mode, expectedPalette]) => {
        describe(`${themeName} Switch (${mode} mode)`, () => {
            const renderSwitch = (props = {}) => render(_jsx(RDSThemeProvider, { themeMap: themeMap, themeMode: mode, children: _jsx(Switch, { ...props }) }));
            describe("Checked Behavior", () => {
                it("applies correct colors for a checked enabled Switch (track and thumb)", () => {
                    renderSwitch({ checked: true });
                    const track = document.querySelector(".MuiSwitch-track");
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    expect(track).toHaveStyle(`background-color: ${expectedPalette.success.main}`);
                    expect(thumb).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.thumb.main.checked}`);
                });
                it("applies correct colors for a checked disabled Switch (track and thumb)", () => {
                    renderSwitch({ checked: true, disabled: true });
                    const track = document.querySelector(".MuiSwitch-track");
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    const switchBase = document.querySelector(".MuiSwitch-switchBase");
                    expect(switchBase).toHaveClass("Mui-disabled");
                    expect(track).toHaveStyle(`background-color: ${expectedPalette.success.main}`);
                    expect(thumb).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.thumb.disabled.checked}`);
                });
                it("applies checked colors for an uncontrolled Switch with defaultChecked", () => {
                    renderSwitch({ defaultChecked: true });
                    const track = document.querySelector(".MuiSwitch-track");
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    const switchBase = document.querySelector(".MuiSwitch-switchBase");
                    expect(switchBase).toHaveClass("Mui-checked");
                    expect(track).toHaveStyle(`background-color: ${expectedPalette.success.main}`);
                    expect(thumb).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.thumb.main.checked}`);
                });
            });
            describe("Unchecked Behavior", () => {
                it("applies correct colors for an unchecked enabled Switch (track and thumb)", () => {
                    renderSwitch();
                    const track = document.querySelector(".MuiSwitch-track");
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    expect(track).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.track.main.unchecked}`);
                    expect(thumb).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.thumb.main.unchecked}`);
                });
                it("applies correct colors for an unchecked disabled Switch (track and thumb)", () => {
                    renderSwitch({ disabled: true });
                    const track = document.querySelector(".MuiSwitch-track");
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    const switchBase = document.querySelector(".MuiSwitch-switchBase");
                    expect(switchBase).toHaveClass("Mui-disabled");
                    expect(track).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.track.main.unchecked}`);
                    expect(thumb).toHaveStyle(`background-color: ${expectedPalette.components?.switch?.thumb.disabled.unchecked}`);
                });
            });
            describe("Opacity", () => {
                it("sets opacity to 1 for an enabled Switch", () => {
                    renderSwitch({ checked: true });
                    const switchRoot = document.querySelector(".MuiSwitch-root");
                    const track = document.querySelector(".MuiSwitch-track");
                    expect(switchRoot).not.toHaveStyle("opacity: 0.5");
                    expect(track).toHaveStyle("opacity: 1");
                });
                it("sets opacity to 0.5 for a disabled Switch", () => {
                    renderSwitch({ checked: true, disabled: true });
                    const switchRoot = document.querySelector(".MuiSwitch-root");
                    const switchBase = document.querySelector(".MuiSwitch-switchBase");
                    expect(switchBase).toHaveClass("Mui-disabled");
                    expect(switchRoot).toHaveStyle("opacity: 0.5");
                });
            });
            describe("Focus Behavior", () => {
                it("applies a focus ring to the track when the Switch is focus visible", () => {
                    renderSwitch();
                    const switchBase = document.querySelector(".MuiSwitch-switchBase");
                    const track = document.querySelector(".MuiSwitch-track");
                    switchBase?.classList.add("Mui-focusVisible");
                    expect(track).toHaveStyle(`outline-color: ${expectedPalette.components?.switch?.focusRing}`);
                    expect(track).toHaveStyle("outline-width: 2px");
                    expect(track).toHaveStyle("outline-style: solid");
                    expect(track).toHaveStyle("outline-offset: 2px");
                });
            });
            describe("Size", () => {
                it("should apply correct thumb and track sizes for small Switch", () => {
                    renderSwitch({ size: "small" });
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    const track = document.querySelector(".MuiSwitch-track");
                    expect(thumb).toHaveStyle("height: 12px");
                    expect(thumb).toHaveStyle("width: 12px");
                    expect(track).toHaveStyle("width: 32px");
                });
                it("should apply correct thumb and switch root sizes for medium Switch", () => {
                    renderSwitch({ size: "medium" });
                    const thumb = document.querySelector(".MuiSwitch-thumb");
                    const track = document.querySelector(".MuiSwitch-track");
                    expect(thumb).toHaveStyle("height: 16px");
                    expect(thumb).toHaveStyle("width: 16px");
                    expect(track).toHaveStyle("width: 43px");
                });
            });
        });
    });
});
